/* ===== V121: تلف السمك — ينقص من المخزن وينحفظ بسجل ===== */
function wasteRender(){
  const f=settings.fish||{}, L=(f.wasteLog||[]), box=document.getElementById('fWasteLog'), tot=document.getElementById('fWasteTot'); if(!box) return;
  const since=(settings.rstAt&&settings.rstAt.fish)||0, sum=L.filter(x=>x.ts>=since).reduce((s,x)=>s+(+x.kg||0),0);
  tot.textContent=(Math.round(sum*100)/100)+' كغم';
  box.innerHTML=L.slice(-6).reverse().map(x=>`<div class="wl-row"><span>${new Date(x.ts).toLocaleDateString('ar-IQ-u-nu-latn',{weekday:'short',day:'numeric',month:'numeric'})}، ${new Date(x.ts).toLocaleTimeString('ar-IQ-u-nu-latn',{hour:'numeric',minute:'2-digit'})}</span><b>${x.kg} كغم</b><button class="btn-sm" type="button" data-wdel="${x.ts}">تراجع</button></div>`).join('');
  box.querySelectorAll('[data-wdel]').forEach(b=>b.addEventListener('click',()=>{ const ts=+b.dataset.wdel, e=(settings.fish.wasteLog||[]).find(x=>x.ts===ts); if(!e) return;
    uiYes('تتراجع عن تلف '+e.kg+' كغم؟',()=>{ settings.fish.wasteLog=settings.fish.wasteLog.filter(x=>x!==e); settings.fish.used=Math.max(0,Math.round(((settings.fish.used||0)-e.kg)*100)/100); saveAll(); fishCalc(); wasteRender(); toast('رجع '+e.kg+' كغم') }) }));
}
document.getElementById('fWasteBtn').addEventListener('click',()=>{
  const v=parseFloat(document.getElementById('fWaste').value); if(!(v>0)){ toast('اكتب كم كيلو تلف'); return }
