    const f=settings.fish; f.wasteLog=(f.wasteLog||[]).concat([{ts:Date.now(),kg:v}]).slice(-200);
    f.used=Math.round(((f.used||0)+v)*100)/100; document.getElementById('fWaste').value='';
    saveAll(); fishCalc(); wasteRender(); try{ lowCheck() }catch(_){} toast('انسجل تلف '+v+' كغم');
  });
});
